import React, { useEffect, useState } from "react";

import useApi from "../../../../hooks/useApi";
import { useNavigate, useParams } from "react-router-dom";
import departmentsApi from "../../../../api/departmentsApi";
import { Loading } from "../../../../components";
import EntityLaboratoryServicesFormModal from "./EntityLaboratoryServicesFormModal";
import EntityLaboratoryServicesTable from "./EntityLaboratoryServicesTable";
import hospitalsApi from "../../../../api/hospitals/hospitalsApi";
import { useStateContext } from "../../../../contexts/ContextProvider";

const columns = [
  { name: "Title", uid: "laboratory_service_title" },
  { name: "Charge", uid: "charge" },
  { name: "Date", uid: "created" },
  { name: "Actions", uid: "actions" },
];

function EntityLaboratoryServicesList() {
  const [openInventoryFormModal, setopenInventoryFormModal] = useState(false);
  const navigate = useNavigate();
  const [selectedPhysiotherapyService, setselectedPhysiotherapyService] = useState();
  const [entityLaboratoryServices, setentityLaboratoryServices] = useState([]);
  const [data, setdata] = useState([]);
  const [modalTitle, setmodalTitle] = useState("");
  const [updated, setUpdated] = useState(false);
  const {loggedInUser}= useStateContext()

  const entityLaboratoryServicesApi = useApi(hospitalsApi.hospitalStaffAction);





  const getEntitylaboratoryServices = async (data) => {

    await entityLaboratoryServicesApi.request({
      "action":"GetEntityLaboratoryServices",
      "department":loggedInUser.employment_department
  });
  };

  useEffect(() => {
    if (entityLaboratoryServicesApi.data) {
      if (entityLaboratoryServicesApi.data.length) {
        setentityLaboratoryServices(entityLaboratoryServicesApi.data);
      }
    }
  }, [entityLaboratoryServicesApi.data]);

  useEffect(() => {

    getEntitylaboratoryServices();


  }, []);

  useEffect(() => {
    setdata(entityLaboratoryServices);
  }, [entityLaboratoryServices]);

  const handleEditAction = (item) => {
    setopenInventoryFormModal(true);
    setselectedPhysiotherapyService(item);
    setmodalTitle(`EDIT ${item.laboratory_service_title}`);
    setUpdated(false)
  };

  const handleAddAction = () => {
    setopenInventoryFormModal(true);
    setmodalTitle("Add new pathology service");
    setselectedPhysiotherapyService(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/systems/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    console.log("Item", item);
    navigate(`/systems/delete/${item.id}`);
  };

  useEffect(() => {
    if (entityLaboratoryServicesApi.data && entityLaboratoryServicesApi.data.length) {
      setentityLaboratoryServices(entityLaboratoryServicesApi.data);
    }
    console.log("entityLaboratoryServicesApi.data", entityLaboratoryServicesApi.data);
  }, [entityLaboratoryServicesApi.data]);

  useEffect(() => {
    if (updated === true) {

      getEntitylaboratoryServices();
    }
  }, [updated]);

  //Filtering data
  useEffect(() => {
    setdata(entityLaboratoryServices);
  }, [entityLaboratoryServices]);

  const handleFilter = (e) => {
    const search_param = e;
    if (
      entityLaboratoryServices &&
      entityLaboratoryServices.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setdata(
        entityLaboratoryServices.filter((x) => x.title.toLowerCase().includes(search_param))
      );
    } else {
      setdata(entityLaboratoryServices);
    }
  };

  return entityLaboratoryServicesApi.loading ? (
    <Loading loading={departmentsApi.loading} />
  ) : (
    <div className="mt-16 md:mt-2">
        {openInventoryFormModal && (
          <EntityLaboratoryServicesFormModal
            ismodalOpen={openInventoryFormModal}
            setisModalOpen={setopenInventoryFormModal}
            selectedPhysiotherapyService={selectedPhysiotherapyService}
            updated={updated}
            setUpdated={setUpdated}
            modalTitle={modalTitle}
          />
        )}

        <EntityLaboratoryServicesTable
      title={"Entity Laboratory Services"}
        data={data}
        columns={columns}
        editAction={handleEditAction}
        detailsAction={handleDetailsAction}
        deleteAction={handleDeleteAction}
        addAction={handleAddAction}
        handleFilter={handleFilter}
      />
    </div>
  );
}

export default EntityLaboratoryServicesList;
